contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address caller) public {
        uint256 beforeBalance = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 afterContractBalance = address(c).balance;

        assert(
            beforeBalance != 0 ||
            !reverted ||
            (afterBalance == 0 && afterContractBalance == beforeContractBalance)
        );
    }
}

