pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address caller) internal {
        uint256 beforeBalance;
        try c.balances(caller) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 beforeContractBalance = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance;
        try c.balances(caller) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint256 afterContractBalance = address(c).balance;
        assertTrue(beforeBalance != 0 ||
            !reverted ||
            (afterBalance == 0 && afterContractBalance == beforeContractBalance));
    }

